        impl core::fmt::Display for UnknownSingletonSortedIndexKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(f, "unknown singleton sorted index kind: {}", self.0)
            }
        }
