    #[test]
    fn assert_closed_set_well_formed_catches_walks_all_drift_in_sorted_antimodal_variants() {
        // Drift catch — clause (130)'s full-set + doubled-full-set arms
        // fire when an override walks `T::ALL` (declaration order)
        // instead of `T::sorted_variants()` (lex order) on a closed set
        // where `T::first() != T::sorted_first()`. On ZetaAlphaBeta the
        // declaration order is [Zeta, Alpha, Beta] and the lex order is
        // [Alpha, Beta, Zeta]; on the full-set slice every count is
        // `1`, so the declaration-order argmin filter yields
        // [Zeta, Alpha, Beta] (T::ALL) while the pinned lex-order
        // argmin yields [Alpha, Beta, Zeta] (T::sorted_variants()); the
        // two bifurcate loudly at the full-set + doubled-full-set arms.
        // LOAD-BEARING as the drift catch for the exact shape of an
        // override that accidentally reuses `T::antimodal_variants` (or
        // an inline `T::ALL.iter()...filter(...).collect()`) for the
        // sorted argmin.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedSortedAntimodalVariantsWalksAllKind {
            Zeta,
            Alpha,
            Beta,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedSortedAntimodalVariantsWalksAllKind(pub String);

        impl core::fmt::Display for UnknownDriftedSortedAntimodalVariantsWalksAllKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted sorted_antimodal_variants walks all kind: {}",
                    self.0
                )
            }
        }

        impl DriftedSortedAntimodalVariantsWalksAllKind {
            const ALL: [Self; 3] = [Self::Zeta, Self::Alpha, Self::Beta];
        }

        impl ClosedSet for DriftedSortedAntimodalVariantsWalksAllKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted sorted_antimodal_variants walks all kind";
            type Unknown = UnknownDriftedSortedAntimodalVariantsWalksAllKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Zeta => "zeta",
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedSortedAntimodalVariantsWalksAllKind(s.to_owned())
            }
            fn sorted_antimodal_variants(items: &[Self]) -> Vec<Self> {
                // Drift shape: walks T::ALL instead of T::sorted_variants
                // — the same body as antimodal_variants. Correct on
                // empty + matching-singleton but BIFURCATES at the full-
                // set + doubled-full-set flat-histogram fixpoints
                // because T::first() (Zeta) != T::sorted_first() (Alpha).
                <Self as ClosedSet>::antimodal_variants(items)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedSortedAntimodalVariantsWalksAllKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedSortedAntimodalVariantsWalksAllKind whose sorted_antimodal_variants override walks T::ALL instead of T::sorted_variants — clause (130)'s full-set + doubled-full-set arms MUST reject the drift when T::first() != T::sorted_first()",
        );
    }

    #[test]
    fn count_modal_variants_returns_zero_on_the_empty_slice_across_every_kind() {
        // EMPTY-SLICE CONTRACT (set-level × usize × statistical-aggregate
        // × direction × argmax cardinality-count projection):
        // `T::count_modal_variants(&[])` is `0` UNCONDITIONALLY — the
        // empty slice hits zero positions, `T::max_variant_count(&[])`
        // collapses to `0`, and an UNGUARDED `T::ALL.iter().filter(|v|
        // count(v) == 0).count()` sweep would silently return
        // `T::CARDINALITY` past the (max == 0, every-count == 0)
        // degenerate arm where every variant satisfies the vacuous
        // `0 == 0` predicate — the empty-slice guard maps `&[]` to `0`
        // before the sweep. Sibling posture to
        // `modal_variants_returns_the_empty_vec_on_the_empty_slice_across_every_kind`
        // one return-shape axis over: the set-level Vec-return
        // complete-witness collapses to the empty vector at the empty
        // slice; this projection collapses to `0` at the same endpoint.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::count_modal_variants(empty),
            0,
            "T::count_modal_variants(&[]) diverged from the empty-slice fixpoint `0`",
        );
    }

    #[test]
    fn count_modal_variants_returns_one_on_every_singleton_across_every_variant() {
        // SINGLETON CONTRACT: `T::count_modal_variants(&[v])` is `1` for
        // every variant `v` — a singleton slice hits exactly one variant
        // at exactly one position, `T::max_variant_count([v])` collapses
        // to `1`, and only the target `v` satisfies `count == max` (the
        // other variants have count `0`, failing the predicate). Sibling
        // posture to
        // `modal_variants_returns_the_target_only_on_every_matching_singleton_across_every_variant`
        // one return-shape axis over: the set-level Vec-return
        // complete-witness collapses to `vec![target]` on every matching
        // singleton; this projection collapses to `1` at the same
        // endpoint.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert_eq!(
                <StubKind as ClosedSet>::count_modal_variants(&singleton),
                1,
                "T::count_modal_variants({singleton:?}) diverged from the singleton fixpoint `1`",
            );
        }
    }

    #[test]
    fn count_modal_variants_returns_cardinality_on_the_full_set_across_every_kind() {
        // FULL-SET CONTRACT: `T::count_modal_variants(T::ALL)` is
        // `T::CARDINALITY` UNCONDITIONALLY — the closed-set well-
        // formedness invariant `assert_closed_set_well_formed`'s clause
        // (3) pins variants as pairwise distinct, so every variant of
        // `T::ALL` appears at EXACTLY ONE position of the full-set
        // slice; every per-target multiplicity is `1`,
        // `T::max_variant_count(T::ALL)` collapses to `1`, and every
        // variant satisfies `count == max`. Complements
        // `modal_variants_returns_all_on_the_full_set_across_every_kind`
        // one return-shape axis over: the set-level Vec-return
        // complete-witness reaches `T::ALL.to_vec()` at the full set;
        // this count reaches its `T::CARDINALITY` maximum at the same
        // endpoint.
        let all = <StubKind as ClosedSet>::ALL;
        assert_eq!(
            <StubKind as ClosedSet>::count_modal_variants(all),
            <StubKind as ClosedSet>::CARDINALITY,
            "T::count_modal_variants(T::ALL) diverged from the full-set fixpoint `T::CARDINALITY` — the closed-set well-formedness pairwise-distinctness invariant would be violated",
        );
    }

    #[test]
    fn count_modal_variants_returns_cardinality_on_the_doubled_full_set_across_every_kind() {
        // DOUBLED-FULL-SET CONTRACT:
        // `T::count_modal_variants(T::ALL ++ T::ALL)` is
        // `T::CARDINALITY` UNCONDITIONALLY — the doubled full set hits
        // every variant at EXACTLY TWO positions, so every per-target
        // multiplicity is `2`, `T::max_variant_count(doubled)` collapses
        // to `2`, and every variant satisfies `count == max`. Together
        // with the full-set arm (which pins the same `T::CARDINALITY`
        // fixpoint at max `== 1`), the doubled-full-set arm demonstrates
        // that the projection is INVARIANT under uniform slice-
        // multiplication on flat-histogram slices — pinning the
        // projection as a MODAL-TIE cardinality rather than the modal-
        // multiplicity scalar `T::max_variant_count` which TRANSITIONS
        // from `1` to `2` between the two flat-histogram fixpoints.
        let doubled: Vec<StubKind> = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .chain(<StubKind as ClosedSet>::ALL.iter().copied())
            .collect();
        assert_eq!(
            <StubKind as ClosedSet>::count_modal_variants(&doubled),
            <StubKind as ClosedSet>::CARDINALITY,
            "T::count_modal_variants(ALL++ALL) diverged from the doubled-full-set fixpoint `T::CARDINALITY`",
        );
    }

