    #[test]
    fn count_modal_variants_is_bounded_above_by_cardinality_and_count_distinct_across_every_triple()
    {
        // BOUNDED-ABOVE CONTRACT: for every slice `items`,
        // `T::count_modal_variants(items) <= T::CARDINALITY` AND on
        // non-empty slices `T::count_modal_variants(items) <=
        // T::count_distinct(items)` — the count is bounded above by
        // the ambient cardinality (there are only `T::CARDINALITY`
        // variants to sample from) AND by the count of PRESENT
        // variants (a modal variant on a non-empty slice achieves
        // `max >= 1`, so it is a fortiori present with mult `>= 1`).
        // Sweeping every length-3 triple pins the pair of upper bounds
        // across the full 27-corner (triple) domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let modal_count = <StubKind as ClosedSet>::count_modal_variants(&triple);
                    assert!(
                        modal_count <= <StubKind as ClosedSet>::CARDINALITY,
                        "T::count_modal_variants({triple:?}) = {modal_count} exceeds T::CARDINALITY = {cardinality} — the set-level modal-tie count MUST be bounded above by the ambient cardinality",
                        cardinality = <StubKind as ClosedSet>::CARDINALITY,
                    );
                    let distinct_count = <StubKind as ClosedSet>::count_distinct(&triple);
                    assert!(
                        modal_count <= distinct_count,
                        "T::count_modal_variants({triple:?}) = {modal_count} exceeds T::count_distinct({triple:?}) = {distinct_count} — the set-level modal-tie count MUST be bounded above by the count of PRESENT variants on non-empty slices because a modal variant achieves `max >= 1` and is a fortiori present with mult `>= 1`",
                    );
                }
            }
        }
    }

    #[test]
    fn count_modal_variants_is_invariant_under_ordering_axis_across_every_triple() {
        // ORDERING-AXIS INVARIANCE CONTRACT: the projection factors
        // through `count_occurrences_of` + `max_variant_count` (both
        // ordering-agnostic) via a standard-library `filter().count()`
        // combinator over the closed set — so the (declaration, lex)
        // axis COLLAPSES on this count. Cross-checks against the direct
        // filter-count sweep. Sweeping every length-3 triple pins the
        // identity across the full 27-corner (triple) domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_pinned = <StubKind as ClosedSet>::count_modal_variants(&triple);
                    let via_filter = if triple.is_empty() {
                        0
                    } else {
                        let max = <StubKind as ClosedSet>::max_variant_count(&triple);
                        <StubKind as ClosedSet>::ALL
                            .iter()
                            .copied()
                            .filter(|&v| {
                                <StubKind as ClosedSet>::count_occurrences_of(v, &triple) == max
                            })
                            .count()
                    };
                    assert_eq!(
                        via_pinned, via_filter,
                        "T::count_modal_variants({triple:?}) diverged from the direct (`count(v) == max`) filter-count sweep — the ordering-agnostic count projection was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_zero_drift_in_count_modal_variants() {
        // Drift catch — clause (131)'s full-set + doubled-full-set arms
        // fire when an override folds the set-level modal-tie count
        // onto `0` unconditionally. On the full set + doubled-full set
        // that produces `0 != T::CARDINALITY`, tripping the flat-
        // histogram fixpoint arms loudly. Sibling posture to the
        // (`count_unique_variants` → `0` drift catch) one AGGREGATION-
        // KIND axis over: that drift fires on the full-set arm at
        // `0 != T::CARDINALITY`; this drift fires on BOTH flat-
        // histogram arms (full + doubled full) at the same shape.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedCountModalVariantsZeroKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedCountModalVariantsZeroKind(pub String);

        impl core::fmt::Display for UnknownDriftedCountModalVariantsZeroKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted count_modal_variants zero kind: {}",
                    self.0
                )
            }
        }

        impl DriftedCountModalVariantsZeroKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedCountModalVariantsZeroKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted count_modal_variants zero kind";
            type Unknown = UnknownDriftedCountModalVariantsZeroKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedCountModalVariantsZeroKind(s.to_owned())
            }
            fn count_modal_variants(_items: &[Self]) -> usize {
                // Drift: return `0` regardless of slice. On the full set
                // + doubled-full set that produces `0 != T::CARDINALITY`,
                // tripping clause (131)'s flat-histogram fixpoint arms
                // loudly.
                0
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedCountModalVariantsZeroKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedCountModalVariantsZeroKind whose count_modal_variants override folds onto `0` unconditionally — clause (131)'s full-set + doubled-full-set arms MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_cardinality_drift_in_count_modal_variants() {
        // Drift catch — clause (131)'s empty-slice fixpoint arm fires
        // when an override omits the empty-slice guard and returns
        // `T::CARDINALITY` on `&[]` past the (max == 0, every-count == 0)
        // degenerate arm where every variant satisfies the vacuous
        // `0 == 0` predicate. Sibling posture to the drift catches for
        // `modal_variants` / `sorted_modal_variants` empty-slice guard
        // omission one RETURN-SHAPE axis over: those return
        // `T::ALL.to_vec()` / `T::sorted_variants()`; this returns
        // `T::CARDINALITY` (their length).
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedCountModalVariantsCardinalityKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedCountModalVariantsCardinalityKind(pub String);

        impl core::fmt::Display for UnknownDriftedCountModalVariantsCardinalityKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted count_modal_variants cardinality kind: {}",
                    self.0
                )
            }
        }

        impl DriftedCountModalVariantsCardinalityKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedCountModalVariantsCardinalityKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted count_modal_variants cardinality kind";
            type Unknown = UnknownDriftedCountModalVariantsCardinalityKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedCountModalVariantsCardinalityKind(s.to_owned())
            }
            fn count_modal_variants(items: &[Self]) -> usize {
                // Drift shape: omit the empty-slice guard. Correct on
                // every non-empty slice but BIFURCATES at the empty
                // slice, returning T::CARDINALITY past the (max == 0,
                // every-count == 0) degenerate arm where every variant
                // satisfies the vacuous `0 == 0` predicate. Clause
                // (131)'s empty-slice fixpoint arm fires at `T::CARDINALITY
                // != 0`.
                let max = <Self as ClosedSet>::max_variant_count(items);
                <Self as ClosedSet>::ALL
                    .iter()
                    .copied()
                    .filter(|&v| <Self as ClosedSet>::count_occurrences_of(v, items) == max)
                    .count()
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedCountModalVariantsCardinalityKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedCountModalVariantsCardinalityKind whose count_modal_variants override omits the empty-slice guard — clause (131)'s empty-slice fixpoint arm MUST reject the drift",
        );
    }

