    #[test]
    fn count_antimodal_variants_returns_cardinality_minus_one_on_matching_singleton_at_cardinality_gte_two_across_every_kind(
    ) {
        // MATCHING-SINGLETON CONTRACT (cardinality >= 2 branch): a
        // matching singleton `&[v]` hits `count(v) == 1 == max` and
        // `count(w) == 0 == min` for every non-target variant `w != v`.
        // The argmin filter hits every non-target variant, yielding
        // `T::CARDINALITY - 1`. LOAD-BEARING ASYMMETRY against
        // `count_modal_variants` which returns `1` on the same singleton
        // — the (min-arm × singleton) endpoint separates the argmin
        // corner from the argmax corner distinctly on this projection.
        const {
            assert!(
                <StubKind as ClosedSet>::CARDINALITY >= 2,
                "StubKind cardinality changed — this test assumes >= 2 to fire the non-degenerate singleton branch",
            );
        }
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            let actual = <StubKind as ClosedSet>::count_antimodal_variants(&singleton);
            let expected = <StubKind as ClosedSet>::CARDINALITY - 1;
            assert_eq!(
                actual, expected,
                "T::count_antimodal_variants({singleton:?}) diverged from T::CARDINALITY - 1 == {expected} — every non-target variant hits count == 0 == min",
            );
        }
    }

