    #[test]
    fn count_antimodal_variants_equals_count_missing_when_min_is_zero_across_every_triple() {
        // MISSING-COUNT IDENTITY (min == 0 fixpoint): on every slice
        // with `T::min_variant_count(items) == 0` (equivalently,
        // `T::is_missing_any(items)` holds), the argmin cardinality
        // collapses onto the SET-LEVEL MISSING CARDINALITY because
        // every present variant hits count `>= 1 > 0` and every missing
        // variant hits count `== 0 == min`. Sweeping every length-3
        // triple pins the identity across the full 27-corner (triple)
        // domain — the identity does NOT hold on flat-histogram slices
        // where every variant is present (min >= 1), so the sweep
        // filters to the min == 0 arm before asserting.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    if <StubKind as ClosedSet>::min_variant_count(&triple) != 0 {
                        continue;
                    }
                    let via_argmin = <StubKind as ClosedSet>::count_antimodal_variants(&triple);
                    let via_missing = <StubKind as ClosedSet>::count_missing(&triple);
                    assert_eq!(
                        via_argmin, via_missing,
                        "T::count_antimodal_variants({triple:?}) diverged from T::count_missing({triple:?}) on a min == 0 slice — the argmin cardinality MUST equal the set-level missing cardinality when every missing variant achieves count == 0 == min",
                    );
                }
            }
        }
    }

