    #[test]
    fn has_unique_mode_equals_count_modal_variants_eq_one_across_every_triple() {
        // COUNT-COMPOSITION IDENTITY: for every slice `items`,
        // `T::has_unique_mode(items) == (T::count_modal_variants(items) == 1)`
        // — the set-level bool predicate is EXACTLY the strict-equality
        // test of the just-lifted set-level cardinality-count aggregate
        // against `1`. The canonical form the body uses. Sweeping every
        // length-3 triple pins the identity across the full 27-corner
        // (triple) domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate = <StubKind as ClosedSet>::has_unique_mode(&triple);
                    let via_count = <StubKind as ClosedSet>::count_modal_variants(&triple) == 1;
                    assert_eq!(
                        via_predicate, via_count,
                        "T::has_unique_mode({triple:?}) diverged from (T::count_modal_variants({triple:?}) == 1) — the count-composition identity was violated",
                    );
                }
            }
        }
        // Empty-slice endpoint: predicate is `false`, count is `0`,
        // `0 == 1` is `false`.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::has_unique_mode(empty),
            <StubKind as ClosedSet>::count_modal_variants(empty) == 1,
        );
    }

