    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_is_unique_modal_variant_of() {
        // Drift catch — clause (137)'s empty-slice + non-matching-
        // singleton + flat-histogram fixpoint arms fire when an override
        // folds the per-target unique-mode predicate onto `true`
        // unconditionally. Empty-slice arm produces `true != false` at
        // every target; non-matching-singleton arm fires at every non-
        // matching target pair; both flat-histogram fixpoint arms at
        // cardinality `>= 2` fire at every target because the
        // conjunction's uniqueness arm falsifies.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedIsUniqueModalVariantOfTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedIsUniqueModalVariantOfTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedIsUniqueModalVariantOfTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted is_unique_modal_variant_of true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedIsUniqueModalVariantOfTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedIsUniqueModalVariantOfTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted is_unique_modal_variant_of true kind";
            type Unknown = UnknownDriftedIsUniqueModalVariantOfTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedIsUniqueModalVariantOfTrueKind(s.to_owned())
            }
            fn is_unique_modal_variant_of(_target: Self, _items: &[Self]) -> bool {
                // Drift: return `true` regardless of (target, slice).
                // Fires clause (137)'s empty-slice arm at every target
                // (`true != false`), the non-matching-singleton arm at
                // every non-matching target pair, AND both flat-
                // histogram fixpoint arms at cardinality `>= 2` at
                // every target.
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedIsUniqueModalVariantOfTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedIsUniqueModalVariantOfTrueKind whose is_unique_modal_variant_of override folds onto `true` unconditionally — clause (137)'s empty-slice + non-matching-singleton + flat-histogram fixpoint arms MUST reject the drift",
        );
    }

