    #[test]
    fn unique_modal_variant_equals_has_unique_mode_gated_modal_variant_across_every_triple() {
        // GUARDED-FIRST-WITNESS IDENTITY: for every slice `items`,
        // T::unique_modal_variant(items) == if T::has_unique_mode(items)
        // { T::modal_variant(items) } else { None }. The canonical form
        // the body uses.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_body = <StubKind as ClosedSet>::unique_modal_variant(&triple);
                    let via_guarded_lift = if <StubKind as ClosedSet>::has_unique_mode(&triple) {
                        <StubKind as ClosedSet>::modal_variant(&triple)
                    } else {
                        None
                    };
                    assert_eq!(
                        via_body, via_guarded_lift,
                        "T::unique_modal_variant({triple:?}) diverged from the guarded lift `if T::has_unique_mode {{ T::modal_variant }} else {{ None }}`",
                    );
                }
            }
        }
    }

    #[test]
