    #[test]
    fn assert_closed_set_well_formed_catches_always_some_first_drift_in_unique_antimodal_variant() {
        // Drift catch — clause (140)'s empty-slice + full-set + doubled-
        // full-set fixpoint arms fire when an override folds the set-
        // level unique-antimode witness onto `Some(T::first())`
        // unconditionally. On the empty slice T::unique_antimodal_variant
        // must return None (has_unique_antimode is false); on the flat-
        // histogram fixpoints at cardinality >= 2 the same None-arm
        // holds. An always-Some(first) override bifurcates the empty
        // arm loudly at `Some(_) != None`.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedUniqueAntimodalVariantSomeFirstKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedUniqueAntimodalVariantSomeFirstKind(pub String);

        impl core::fmt::Display for UnknownDriftedUniqueAntimodalVariantSomeFirstKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted unique_antimodal_variant some-first kind: {}",
                    self.0
                )
            }
        }

        impl DriftedUniqueAntimodalVariantSomeFirstKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedUniqueAntimodalVariantSomeFirstKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted unique_antimodal_variant some-first kind";
            type Unknown = UnknownDriftedUniqueAntimodalVariantSomeFirstKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedUniqueAntimodalVariantSomeFirstKind(s.to_owned())
            }
            fn unique_antimodal_variant(_items: &[Self]) -> Option<Self> {
                // Drift: always return Some(first). Fires on empty
                // (Some(_) != None) AND on both flat-histogram
                // fixpoints at cardinality >= 2 (Some(_) != None) AND
                // on the matching-singleton fixpoint at cardinality
                // >= 3.
                Some(Self::Alpha)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedUniqueAntimodalVariantSomeFirstKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedUniqueAntimodalVariantSomeFirstKind whose unique_antimodal_variant override folds onto Some(first) unconditionally — clause (140)'s empty-slice + flat-histogram fixpoint arms MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_none_drift_in_unique_antimodal_variant() {
        // Drift catch — clause (140)'s single-missing (omit-last)
        // fixpoint arm fires when an override folds the set-level
        // unique-antimode witness onto `None` unconditionally. The
        // single-missing fixture at cardinality >= 2 pins the projection
        // at Some(omitted_last), so `None != Some(omitted_last)`.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedUniqueAntimodalVariantNoneKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedUniqueAntimodalVariantNoneKind(pub String);

        impl core::fmt::Display for UnknownDriftedUniqueAntimodalVariantNoneKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted unique_antimodal_variant none kind: {}",
                    self.0
                )
            }
        }

        impl DriftedUniqueAntimodalVariantNoneKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedUniqueAntimodalVariantNoneKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted unique_antimodal_variant none kind";
            type Unknown = UnknownDriftedUniqueAntimodalVariantNoneKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedUniqueAntimodalVariantNoneKind(s.to_owned())
            }
            fn unique_antimodal_variant(_items: &[Self]) -> Option<Self> {
                // Drift: always return None. Fires on the single-
                // missing (omit-last) fixture arm (None != Some(omitted_last)).
                None
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedUniqueAntimodalVariantNoneKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedUniqueAntimodalVariantNoneKind whose unique_antimodal_variant override folds onto None unconditionally — clause (140)'s single-missing fixpoint arm MUST reject the drift",
        );
    }

    #[test]
    fn is_extremal_variant_of_returns_false_on_the_empty_slice_across_every_target() {
        // EMPTY-SLICE CONTRACT (per-target × bool × statistical-
        // aggregate × direction-agnostic × union): T::is_extremal_variant_of(v, &[])
        // == false for every target v UNCONDITIONALLY — both direction
        // siblings collapse to `false` via their shared non-emptiness
        // guards, and the disjunction lands on `false` at every target
        // through both arms.
        let empty: &[StubKind] = &[];
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            assert!(
                !<StubKind as ClosedSet>::is_extremal_variant_of(v, empty),
                "T::is_extremal_variant_of({v:?}, &[]) diverged from the empty-slice fixpoint `false`",
            );
        }
    }

    #[test]
    fn is_extremal_variant_of_returns_true_on_the_matching_singleton_across_every_target() {
        // MATCHING-SINGLETON CONTRACT AT CARDINALITY >= 2:
        // T::is_extremal_variant_of(v, [v]) == true for every variant v —
        // the sole position hits the target at count 1 == max,
        // is_modal_variant_of reports `true`, the disjunction lands on
        // `true` through the argmax arm. LOAD-BEARING `true`-arm catch.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert!(
                <StubKind as ClosedSet>::is_extremal_variant_of(v, &singleton),
                "T::is_extremal_variant_of({v:?}, [{v:?}]) diverged from `true` on the matching-singleton fixpoint",
            );
        }
    }

    #[test]
    fn is_extremal_variant_of_returns_true_on_the_non_matching_singleton_across_every_target_pair()
    {
        // NON-MATCHING-SINGLETON CONTRACT AT CARDINALITY >= 2:
        // T::is_extremal_variant_of(v, [w]) == true for every target v
        // and slice-element w with v != w — the sole position hits w,
        // not v; the target's count is 0 == min, is_antimodal_variant_of
        // reports `true` on the argmin band, and the disjunction lands
        // on `true` through the argmin arm.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            for w in <StubKind as ClosedSet>::ALL.iter().copied() {
                if <StubKind as ClosedSet>::index_of(v) == <StubKind as ClosedSet>::index_of(w) {
                    continue;
                }
                let singleton = [w];
                assert!(
                    <StubKind as ClosedSet>::is_extremal_variant_of(v, &singleton),
                    "T::is_extremal_variant_of({v:?}, [{w:?}]) diverged from `true` on the non-matching-singleton fixpoint (target sits at min)",
                );
            }
        }
    }

