    #[test]
    fn is_extremal_variant_of_returns_false_at_middle_band_target_on_the_bimodal_triple_at_cardinality_ge_three(
    ) {
        // MIDDLE-BAND CONTRACT AT CARDINALITY >= 3: on the bimodal
        // triple [T::ALL[0], T::ALL[0], T::ALL[1]] the histogram is
        // (T::ALL[0] -> 2 == max, T::ALL[1] -> 1 == MIDDLE, T::ALL[2] ->
        // 0 == min). T::is_extremal_variant_of returns `true` at both
        // direction endpoints (T::ALL[0] and T::ALL[2]) and `false` at
        // the middle-band target T::ALL[1]. The LOAD-BEARING `false`-
        // arm catch on the union corner at cardinality >= 3.
        const {
            assert!(
                <StubKind as ClosedSet>::CARDINALITY >= 3,
                "StubKind cardinality changed — this test assumes >= 3 for the bimodal-triple fixture to have a middle band",
            );
        }
        let bimodal_triple = [
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[1],
        ];
        let modal_target = <StubKind as ClosedSet>::ALL[0];
        let middle_target = <StubKind as ClosedSet>::ALL[1];
        let antimodal_target = <StubKind as ClosedSet>::ALL[2];
        assert!(
            <StubKind as ClosedSet>::is_extremal_variant_of(modal_target, &bimodal_triple),
            "T::is_extremal_variant_of({modal_target:?}, {bimodal_triple:?}) diverged from `true` at the argmax endpoint",
        );
        assert!(
            !<StubKind as ClosedSet>::is_extremal_variant_of(middle_target, &bimodal_triple),
            "T::is_extremal_variant_of({middle_target:?}, {bimodal_triple:?}) diverged from `false` at the middle-band target — the LOAD-BEARING `false`-arm catch on the union corner",
        );
        assert!(
            <StubKind as ClosedSet>::is_extremal_variant_of(antimodal_target, &bimodal_triple),
            "T::is_extremal_variant_of({antimodal_target:?}, {bimodal_triple:?}) diverged from `true` at the argmin endpoint",
        );
    }

    #[test]
    fn is_extremal_variant_of_equals_is_modal_or_antimodal_variant_of_across_every_target_and_triple(
    ) {
        // DIRECTION-UNION IDENTITY: for every slice `items` and every
        // target v, T::is_extremal_variant_of(v, items) ==
        // (T::is_modal_variant_of(v, items) ||
        // T::is_antimodal_variant_of(v, items)). The canonical form the
        // body uses.
        for target in <StubKind as ClosedSet>::ALL.iter().copied() {
            for a in <StubKind as ClosedSet>::ALL.iter().copied() {
                for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                    for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let triple = [a, b, c];
                        let via_predicate =
                            <StubKind as ClosedSet>::is_extremal_variant_of(target, &triple);
                        let via_disjunction =
                            <StubKind as ClosedSet>::is_modal_variant_of(target, &triple)
                                || <StubKind as ClosedSet>::is_antimodal_variant_of(
                                    target, &triple,
                                );
                        assert_eq!(
                            via_predicate, via_disjunction,
                            "T::is_extremal_variant_of({target:?}, {triple:?}) diverged from (T::is_modal_variant_of({target:?}, {triple:?}) || T::is_antimodal_variant_of({target:?}, {triple:?})) — the direction-union identity was violated",
                        );
                    }
                }
            }
        }
    }

