    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_is_extremal_variant_of() {
        // Drift catch — clause (141)'s empty-slice + middle-band
        // fixpoint arms fire when an override folds the per-target
        // direction-agnostic extremity predicate onto `true`
        // unconditionally.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedIsExtremalVariantOfTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedIsExtremalVariantOfTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedIsExtremalVariantOfTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted is_extremal_variant_of true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedIsExtremalVariantOfTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedIsExtremalVariantOfTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted is_extremal_variant_of true kind";
            type Unknown = UnknownDriftedIsExtremalVariantOfTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedIsExtremalVariantOfTrueKind(s.to_owned())
            }
            fn is_extremal_variant_of(_target: Self, _items: &[Self]) -> bool {
                // Drift: return `true` regardless. Fires on the empty-
                // slice arm at every target AND on the middle-band arm
                // at target Beta on the bimodal-triple fixture at
                // cardinality >= 3.
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedIsExtremalVariantOfTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedIsExtremalVariantOfTrueKind whose is_extremal_variant_of override folds onto `true` unconditionally — clause (141)'s empty-slice + middle-band fixpoint arms MUST reject the drift",
        );
    }

