    #[test]
    fn is_bimodal_variant_of_returns_false_on_the_empty_slice_across_every_target() {
        // EMPTY-SLICE CONTRACT (per-target × bool × statistical-
        // aggregate × direction-agnostic × intersection):
        // T::is_bimodal_variant_of(v, &[]) == false for every target v
        // UNCONDITIONALLY — both direction siblings collapse to `false`
        // via their shared non-emptiness guards, and the conjunction
        // lands on `false` at every target through both arms.
        let empty: &[StubKind] = &[];
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            assert!(
                !<StubKind as ClosedSet>::is_bimodal_variant_of(v, empty),
                "T::is_bimodal_variant_of({v:?}, &[]) diverged from the empty-slice fixpoint `false`",
            );
        }
    }

    #[test]
    fn is_bimodal_variant_of_returns_false_on_the_matching_singleton_across_every_target() {
        // MATCHING-SINGLETON CONTRACT AT CARDINALITY >= 2:
        // T::is_bimodal_variant_of(v, [v]) == false for every variant v
        // — the sole position hits the target at count `1 == max`, but
        // at cardinality >= 2 at least one non-target variant sits at
        // count `0 == min`, so is_antimodal_variant_of reports `false`
        // at the target, and the conjunction lands on `false` through
        // the argmin arm. LOAD-BEARING `false`-arm catch separating
        // this corner from is_extremal_variant_of.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert!(
                !<StubKind as ClosedSet>::is_bimodal_variant_of(v, &singleton),
                "T::is_bimodal_variant_of({v:?}, [{v:?}]) diverged from `false` on the matching-singleton fixpoint at cardinality >= 2",
            );
        }
    }

    #[test]
    fn is_bimodal_variant_of_returns_false_on_the_non_matching_singleton_across_every_target_pair()
    {
        // NON-MATCHING-SINGLETON CONTRACT AT CARDINALITY >= 2:
        // T::is_bimodal_variant_of(v, [w]) == false for every target v
        // and slice-element w with v != w — the sole position hits w,
        // not v; the target's count is 0 == min, but w's count is
        // 1 == max, so is_modal_variant_of reports `false` at the
        // target, and the conjunction lands on `false` through the
        // argmax arm.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            for w in <StubKind as ClosedSet>::ALL.iter().copied() {
                if <StubKind as ClosedSet>::index_of(v) == <StubKind as ClosedSet>::index_of(w) {
                    continue;
                }
                let singleton = [w];
                assert!(
                    !<StubKind as ClosedSet>::is_bimodal_variant_of(v, &singleton),
                    "T::is_bimodal_variant_of({v:?}, [{w:?}]) diverged from `false` on the non-matching-singleton fixpoint (target sits at min but w sits at max)",
                );
            }
        }
    }

