    #[test]
    fn count_bimodal_variants_lands_in_the_two_value_dichotomy_across_every_triple() {
        // TWO-VALUE DICHOTOMY IDENTITY: for every slice `items`,
        // `T::count_bimodal_variants(items) ∈ {0, T::CARDINALITY}` — the
        // arity-lift's image is the two-point set: zero on every non-
        // flat slice AND on the empty slice, T::CARDINALITY on every
        // non-empty flat-histogram slice. No intermediate values are
        // reachable, distinguishing this projection from the direction-
        // anchored T::count_modal_variants / T::count_antimodal_variants
        // pair which span the full `[0, T::CARDINALITY]` range.
        // Sweeping every length-3 triple pins the identity across the
        // full 27-corner (triple) domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let count = <StubKind as ClosedSet>::count_bimodal_variants(&triple);
                    assert!(
                        count == 0 || count == <StubKind as ClosedSet>::CARDINALITY,
                        "T::count_bimodal_variants({triple:?}) = {count} not in {{0, T::CARDINALITY}} — the intersection cardinality's image MUST be the two-point set {{0, T::CARDINALITY}} because the underlying flat-diagonal predicate reports `true` at EVERY target on flat-histogram non-empty slices AND at NO target otherwise",
                    );
                }
            }
        }
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::count_bimodal_variants(empty),
            0,
            "T::count_bimodal_variants(&[]) diverged from `0` — the empty slice MUST be the SOLE zero-arm that ALSO satisfies T::is_uniform trivially, so the guarded scalar branch MUST land on `0`",
        );
    }

    #[test]
    fn count_bimodal_variants_is_bounded_above_by_count_modal_variants_across_every_triple() {
        // UNION-REFINEMENT IDENTITY: for every slice `items`,
        // `T::count_bimodal_variants(items) <= T::count_modal_variants(
        // items)` AND `T::count_bimodal_variants(items) <=
        // T::count_antimodal_variants(items)` — the intersection
        // cardinality is bounded above by BOTH direction siblings'
        // cardinality-counts (a witness that the corner SHARPENS both
        // direction arms simultaneously into the flat-diagonal slot).
        // Sweeping every length-3 triple pins the pair of upper bounds
        // across the full 27-corner (triple) domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let bimodal = <StubKind as ClosedSet>::count_bimodal_variants(&triple);
                    let modal = <StubKind as ClosedSet>::count_modal_variants(&triple);
                    let antimodal = <StubKind as ClosedSet>::count_antimodal_variants(&triple);
                    assert!(
                        bimodal <= modal,
                        "T::count_bimodal_variants({triple:?}) = {bimodal} exceeds T::count_modal_variants({triple:?}) = {modal} — the intersection cardinality MUST be bounded above by the argmax cardinality on every slice",
                    );
                    assert!(
                        bimodal <= antimodal,
                        "T::count_bimodal_variants({triple:?}) = {bimodal} exceeds T::count_antimodal_variants({triple:?}) = {antimodal} — the intersection cardinality MUST be bounded above by the argmin cardinality on every slice",
                    );
                }
            }
        }
    }

