    #[test]
    fn count_middle_band_variants_equals_filter_count_of_is_middle_band_variant_of_across_every_triple(
    ) {
        // FILTER-COUNT IDENTITY: for every slice `items`,
        // T::count_middle_band_variants(items) == T::ALL.iter().copied().
        // filter(|&v| T::is_middle_band_variant_of(v, items)).count() —
        // the sharpened De Morgan complement body agrees with the naive
        // per-target filter-count reduction over T::ALL. Sweeping every
        // length-3 triple pins the identity across the full 27-corner
        // (triple) domain. Catches a future override that detaches from
        // the arity-lift of the per-target predicate.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_sharpened =
                        <StubKind as ClosedSet>::count_middle_band_variants(&triple);
                    let via_filter = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .filter(|&v| <StubKind as ClosedSet>::is_middle_band_variant_of(v, &triple))
                        .count();
                    assert_eq!(
                        via_sharpened, via_filter,
                        "T::count_middle_band_variants({triple:?}) diverged from the naive filter-count sweep over T::ALL of T::is_middle_band_variant_of — the sharpened De Morgan complement body MUST agree with the per-target arity-lift on every slice",
                    );
                }
            }
        }
    }

    #[test]
    fn count_middle_band_variants_agrees_with_de_morgan_complement_across_every_triple() {
        // DE MORGAN COMPLEMENT IDENTITY: for every slice `items`,
        // T::count_middle_band_variants(items) == if items.is_empty() { 0
        // } else { T::CARDINALITY - T::count_extremal_variants(items) }
        // — the sharpening pins the canonical body directly. Under the
        // cardinality-upper-bound identity T::count_extremal_variants <=
        // T::CARDINALITY, so the subtraction never underflows on usize.
        // Sweeping every length-3 triple + the empty slice pins the
        // identity.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::count_middle_band_variants(empty),
            0,
            "T::count_middle_band_variants(&[]) diverged from `0` on the empty slice — the empty-slice guard MUST short-circuit past the vacuous `T::CARDINALITY - 0` return",
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_pinned = <StubKind as ClosedSet>::count_middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::count_extremal_variants(&triple);
                    let via_arithmetic = <StubKind as ClosedSet>::CARDINALITY - extremal;
                    assert_eq!(
                        via_pinned, via_arithmetic,
                        "T::count_middle_band_variants({triple:?}) diverged from the De Morgan complement arithmetic T::CARDINALITY - count_extremal = {} - {extremal} — the sharpened body MUST agree with the arithmetic composition on every non-empty slice",
                        <StubKind as ClosedSet>::CARDINALITY,
                    );
                }
            }
        }
    }

    #[test]
    fn count_middle_band_variants_plus_count_extremal_variants_equals_cardinality_on_non_empty_across_every_triple(
    ) {
        // PARTITION-SUM IDENTITY: for every NON-EMPTY slice `items`,
        // T::count_middle_band_variants(items) +
        // T::count_extremal_variants(items) == T::CARDINALITY. The
        // (extreme / middle) partition of T::ALL on non-empty slices sums
        // to the full carrier cardinality. Sweeping every length-3 triple
        // pins the identity across the full 27-corner (triple) domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let middle = <StubKind as ClosedSet>::count_middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::count_extremal_variants(&triple);
                    assert_eq!(
                        middle + extremal,
                        <StubKind as ClosedSet>::CARDINALITY,
                        "T::count_middle_band_variants({triple:?}) + T::count_extremal_variants({triple:?}) = {middle} + {extremal} != T::CARDINALITY = {} — the (extreme / middle) partition-sum identity MUST hold on every non-empty slice",
                        <StubKind as ClosedSet>::CARDINALITY,
                    );
                }
            }
        }
    }

    #[test]
    fn count_middle_band_variants_returns_zero_on_every_uniform_non_empty_slice_across_every_triple(
    ) {
        // UNIFORMITY-COLLAPSE IDENTITY: for every NON-EMPTY slice `items`
        // on which T::is_uniform holds (max == min),
        // T::count_middle_band_variants collapses to `0` — the strict-
        // between interval is empty on flat histograms.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    if !<StubKind as ClosedSet>::is_uniform(&triple) || triple.is_empty() {
                        continue;
                    }
                    let middle = <StubKind as ClosedSet>::count_middle_band_variants(&triple);
                    assert_eq!(
                        middle, 0,
                        "T::count_middle_band_variants({triple:?}) = {middle} != 0 on a non-empty uniform slice — the uniformity-collapse identity was violated (the strict-middle band is EMPTY on flat histograms)",
                    );
                }
            }
        }
    }

    #[test]
    fn count_middle_band_variants_is_zero_iff_slice_is_empty_or_uniform_across_every_triple() {
        // EMPTY-OR-UNIFORM-COLLAPSE IDENTITY: for every slice `items`,
        // T::count_middle_band_variants(items) == 0 iff items.is_empty()
        // || T::is_uniform(items) || no target sits strictly between max
        // and min (equivalently, T::count_extremal_variants(items) ==
        // T::CARDINALITY on non-empty slices). This is the two-way
        // biconditional pinning the `0`-arm.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::count_middle_band_variants(empty),
            0,
            "T::count_middle_band_variants(&[]) != 0 — the empty slice MUST hit the `0`-arm",
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let middle = <StubKind as ClosedSet>::count_middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::count_extremal_variants(&triple);
                    let hits_ceiling = extremal == <StubKind as ClosedSet>::CARDINALITY;
                    assert_eq!(
                        middle == 0,
                        hits_ceiling,
                        "T::count_middle_band_variants({triple:?}) == 0 iff T::count_extremal_variants({triple:?}) == T::CARDINALITY — the two-way biconditional between the `0`-arm and the extremal-ceiling was violated (middle={middle}, extremal={extremal}, cardinality={})",
                        <StubKind as ClosedSet>::CARDINALITY,
                    );
                }
            }
        }
    }

