    #[test]
    fn has_middle_band_variant_is_false_iff_slice_is_empty_or_extremal_ceiling_across_every_triple()
    {
        // EMPTY-OR-EXTREMAL-CEILING BICONDITIONAL: for every slice
        // `items`,
        // `!T::has_middle_band_variant(items) iff items.is_empty() || T::count_extremal_variants(items) == T::CARDINALITY`
        // — the middle-band existence bit is `false` EXACTLY when the
        // slice sits on the empty-slice endpoint OR every variant sits
        // at some extreme (union of `is_uniform` slices, singleton
        // slices, and every-variant-extremal fixture). Mirrors the
        // biconditional
        // `count_middle_band_variants_is_zero_iff_slice_is_empty_or_uniform_across_every_triple`
        // one RETURN-SHAPE axis over.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let bit = <StubKind as ClosedSet>::has_middle_band_variant(&triple);
                    let hits_ceiling = <StubKind as ClosedSet>::count_extremal_variants(&triple)
                        == <StubKind as ClosedSet>::CARDINALITY;
                    let empty_or_ceiling = triple.is_empty() || hits_ceiling;
                    assert_eq!(
                        !bit, empty_or_ceiling,
                        "T::has_middle_band_variant({triple:?}) drifted from the empty-or-extremal-ceiling biconditional — !bit MUST equal (items.is_empty() || T::count_extremal_variants(items) == T::CARDINALITY)",
                    );
                }
            }
        }
        let empty: &[StubKind] = &[];
        assert!(!<StubKind as ClosedSet>::has_middle_band_variant(empty));
    }

