    #[test]
    fn has_bimodal_variant_equals_count_bimodal_variants_ge_one_across_every_triple() {
        // COUNT-COMPOSITION IDENTITY: for every slice `items`,
        // `T::has_bimodal_variant(items) == (T::count_bimodal_variants(items) >= 1)`
        // — the canonical form the body uses. Sweeping every length-3
        // triple pins the identity across the full 27-corner domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate = <StubKind as ClosedSet>::has_bimodal_variant(&triple);
                    let via_count = <StubKind as ClosedSet>::count_bimodal_variants(&triple) >= 1;
                    assert_eq!(
                        via_predicate, via_count,
                        "T::has_bimodal_variant({triple:?}) diverged from (T::count_bimodal_variants({triple:?}) >= 1) — the count-composition identity was violated",
                    );
                }
            }
        }
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::has_bimodal_variant(empty),
            <StubKind as ClosedSet>::count_bimodal_variants(empty) >= 1,
        );
    }

    #[test]
    fn has_bimodal_variant_agrees_with_uniformity_collapse_across_every_triple() {
        // UNIFORMITY-COLLAPSE IDENTITY: for every slice `items`,
        // `T::has_bimodal_variant(items) == (!items.is_empty() && T::is_uniform(items))`
        // — the set-level bool predicate collapses to the conjunction of
        // a non-empty guard AND T::is_uniform via the two-value dichotomy
        // of T::count_bimodal_variants (image {0, T::CARDINALITY}).
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate = <StubKind as ClosedSet>::has_bimodal_variant(&triple);
                    let via_uniformity =
                        !triple.is_empty() && <StubKind as ClosedSet>::is_uniform(&triple);
                    assert_eq!(
                        via_predicate, via_uniformity,
                        "T::has_bimodal_variant({triple:?}) diverged from (!items.is_empty() && T::is_uniform({triple:?})) — the uniformity-collapse identity was violated",
                    );
                }
            }
        }
        // Empty-slice endpoint: T::is_uniform(&[]) is trivially `true`
        // via the vacuous (min == max == 0) collapse, but the non-empty
        // guard blocks the conjunction from firing.
        let empty: &[StubKind] = &[];
        let via_predicate = <StubKind as ClosedSet>::has_bimodal_variant(empty);
        let via_uniformity = !empty.is_empty() && <StubKind as ClosedSet>::is_uniform(empty);
        assert_eq!(via_predicate, via_uniformity);
    }

    #[test]
    fn has_bimodal_variant_equals_existential_of_is_bimodal_variant_of_across_every_triple() {
        // EXISTENTIAL-LIFT IDENTITY: for every slice `items`,
        // `T::has_bimodal_variant(items) == T::ALL.iter().copied().any(|v| T::is_bimodal_variant_of(v, items))`
        // — the set-level bool predicate is the EXACT existential
        // quantification over T::ALL of the per-target bimodal predicate.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate = <StubKind as ClosedSet>::has_bimodal_variant(&triple);
                    let via_any = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .any(|v| <StubKind as ClosedSet>::is_bimodal_variant_of(v, &triple));
                    assert_eq!(
                        via_predicate, via_any,
                        "T::has_bimodal_variant({triple:?}) diverged from T::ALL.iter().copied().any(|v| T::is_bimodal_variant_of(v, {triple:?})) — the existential-lift identity was violated",
                    );
                }
            }
        }
        let empty: &[StubKind] = &[];
        let via_predicate = <StubKind as ClosedSet>::has_bimodal_variant(empty);
        let via_any = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .any(|v| <StubKind as ClosedSet>::is_bimodal_variant_of(v, empty));
        assert_eq!(via_predicate, via_any);
    }

    #[test]
    fn has_bimodal_variant_and_has_middle_band_variant_are_mutually_exclusive_on_non_empty_across_every_triple(
    ) {
        // MIDDLE-BAND DE MORGAN IDENTITY: for every NON-EMPTY slice
        // `items`, `T::has_bimodal_variant(items) => !T::has_middle_band_variant(items)`
        // — the flat-diagonal existence bit implies the absence of a
        // middle-band inhabitant. The two existential bits sit on
        // opposite sides of the (intersection / complement) axis of the
        // direction-composition face; they can BOTH be `false` (e.g. a
        // non-flat slice that also has no middle-band inhabitant — a
        // singleton at cardinality >= 2 is non-flat but has every
        // variant at some extreme with none in the middle) but never
        // BOTH `true` on the same non-empty slice.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let bimodal = <StubKind as ClosedSet>::has_bimodal_variant(&triple);
                    let middle_band = <StubKind as ClosedSet>::has_middle_band_variant(&triple);
                    assert!(
                        !(bimodal && middle_band),
                        "T::has_bimodal_variant({triple:?}) = {bimodal} AND T::has_middle_band_variant({triple:?}) = {middle_band} — the two existential bits MUST be mutually exclusive on every non-empty slice; a slice cannot be BOTH flat-diagonal AND have a strictly-between inhabitant simultaneously",
                    );
                }
            }
        }
    }

    #[test]
    fn has_bimodal_variant_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // T::count_bimodal_variants (ordering-agnostic) via a scalar
        // lower-bound test against a fixed constant, so the (declaration,
        // lex) axis on `items` COLLAPSES.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::has_bimodal_variant(&triple);
                    let via_reversed = <StubKind as ClosedSet>::has_bimodal_variant(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::has_bimodal_variant({triple:?}) diverged from T::has_bimodal_variant({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

