    #[test]
    fn extremal_variants_agrees_with_union_of_modal_and_antimodal_variants_across_every_triple() {
        // UNION-COMPOSITION IDENTITY: for every slice `items`,
        // `T::extremal_variants(items)` equals the DECLARATION-ORDER
        // union of `T::modal_variants(items)` and
        // `T::antimodal_variants(items)` as a subset of T::ALL.
        // Cross-check that binds the direction-composition union
        // corner against the direction-anchored pair.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    let modal = <StubKind as ClosedSet>::modal_variants(&triple);
                    let antimodal = <StubKind as ClosedSet>::antimodal_variants(&triple);
                    // Declaration-order union: walk T::ALL, include a
                    // variant iff it appears in modal OR antimodal.
                    let via_union: Vec<StubKind> = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .filter(|v| modal.contains(v) || antimodal.contains(v))
                        .collect();
                    assert_eq!(
                        via_extremal, via_union,
                        "T::extremal_variants({triple:?}) diverged from the declaration-order union of T::modal_variants + T::antimodal_variants — the union-composition identity was violated",
                    );
                }
            }
        }
    }

