    #[test]
    fn middle_band_variants_returns_the_empty_vec_on_the_empty_slice_across_every_kind() {
        // EMPTY-SLICE CONTRACT (set-level × Vec<Self> × statistical-
        // aggregate × direction-composition × complement): the empty
        // slice hits zero positions, T::is_middle_band_variant_of
        // carries a non-emptiness precondition at every target so the
        // complement collection collapses to Vec::new(). The empty
        // guard is LOAD-BEARING for STRUCTURAL correctness — the empty
        // answer is a TYPED CONSEQUENCE of the non-emptiness
        // precondition, not an accidental collision with the strict-
        // interior filter arm on the (max == min == 0) degenerate
        // histogram (which would still yield Vec::new() but for the
        // WRONG structural reason).
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::middle_band_variants(empty),
            Vec::<StubKind>::new(),
            "T::middle_band_variants(&[]) diverged from the empty-slice fixpoint Vec::new()",
        );
    }

    #[test]
    fn middle_band_variants_returns_the_empty_vec_on_every_matching_singleton_across_every_variant()
    {
        // MATCHING-SINGLETON CONTRACT AT CARDINALITY `>= 2`: the sole
        // position hits `v` at count `1 == max` under
        // T::is_modal_variant_of, every non-target variant sits at
        // count `0 == min` under T::is_antimodal_variant_of, so every
        // variant of T::ALL is extremal via one of the two arms and
        // NONE sits strictly between. LOAD-BEARING empty-collection
        // arm DISCRIMINATING this COMPLEMENT projection from
        // T::extremal_variants (which reports T::ALL.to_vec() on the
        // same fixture).
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert_eq!(
                <StubKind as ClosedSet>::middle_band_variants(&singleton),
                Vec::<StubKind>::new(),
                "T::middle_band_variants({singleton:?}) diverged from Vec::new() at the matching-singleton fixpoint at variant {v:?}",
            );
        }
    }

