    #[test]
    fn middle_band_variants_agrees_with_filter_of_is_middle_band_variant_of_across_every_triple() {
        // FILTER-COUNT IDENTITY: for every slice `items`,
        // `T::middle_band_variants(items) == T::ALL.iter().copied().filter(|&v| T::is_middle_band_variant_of(v, items)).collect()`
        // — the sharpened max/min-fold body agrees with the naive
        // per-target filter on the composition-shape axis.
        let empty: &[StubKind] = &[];
        let via_sharpened = <StubKind as ClosedSet>::middle_band_variants(empty);
        let via_naive: Vec<StubKind> = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .filter(|&v| <StubKind as ClosedSet>::is_middle_band_variant_of(v, empty))
            .collect();
        assert_eq!(via_sharpened, via_naive);
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_sharpened = <StubKind as ClosedSet>::middle_band_variants(&triple);
                    let via_naive: Vec<StubKind> = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .filter(|&v| <StubKind as ClosedSet>::is_middle_band_variant_of(v, &triple))
                        .collect();
                    assert_eq!(
                        via_sharpened, via_naive,
                        "T::middle_band_variants({triple:?}) diverged from T::ALL.iter().copied().filter(|v| T::is_middle_band_variant_of(v, {triple:?})).collect() — the filter-count identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn middle_band_variants_agrees_with_set_difference_of_all_and_extremal_variants_across_every_triple(
    ) {
        // COMPLEMENT-COMPOSITION IDENTITY: for every NON-EMPTY slice
        // `items`, `T::middle_band_variants(items)` equals the
        // DECLARATION-ORDER set-difference of T::ALL and
        // T::extremal_variants(items). On the empty slice both sides
        // collapse to Vec::new() via the shared load-bearing empty-
        // slice guard.
        let empty: &[StubKind] = &[];
        let extremal_empty = <StubKind as ClosedSet>::extremal_variants(empty);
        let via_diff_empty: Vec<StubKind> = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .filter(|v| !extremal_empty.contains(v))
            .collect();
        // On the empty slice the naive set-difference walks T::ALL and
        // finds nothing in the empty `extremal_empty`, so it returns
        // T::ALL.to_vec(); the middle-band projection returns Vec::new()
        // via its non-emptiness guard — the (extreme / middle) partition
        // identity holds ONLY on non-empty slices.
        assert_eq!(via_diff_empty.as_slice(), <StubKind as ClosedSet>::ALL);
        assert_eq!(
            <StubKind as ClosedSet>::middle_band_variants(empty),
            Vec::<StubKind>::new(),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_middle_band = <StubKind as ClosedSet>::middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    let via_diff: Vec<StubKind> = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .filter(|v| !extremal.contains(v))
                        .collect();
                    assert_eq!(
                        via_middle_band, via_diff,
                        "T::middle_band_variants({triple:?}) diverged from the declaration-order set-difference of T::ALL and T::extremal_variants({triple:?}) — the complement-composition identity was violated on a non-empty slice",
                    );
                }
            }
        }
    }

    #[test]
    fn middle_band_variants_and_extremal_variants_are_disjoint_across_every_triple() {
        // DISJOINTNESS IDENTITY: for every slice `items`,
        // `T::middle_band_variants(items)` and
        // `T::extremal_variants(items)` share NO common variant — the
        // (extreme / middle) partition of T::ALL on non-empty slices
        // is DISJOINT by construction (a variant's count either sits
        // at max/min or strictly between, never both). On the empty
        // slice both collapse to Vec::new() and disjointness holds
        // trivially.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let middle_band = <StubKind as ClosedSet>::middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    for v in middle_band.iter() {
                        assert!(
                            !extremal.contains(v),
                            "T::middle_band_variants({triple:?}) shares variant {v:?} with T::extremal_variants({triple:?}) — the (extreme / middle) partition disjointness identity was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn middle_band_variants_interleaved_with_extremal_variants_recovers_all_across_every_triple() {
        // INTERLEAVING IDENTITY: for every NON-EMPTY slice `items`,
        // walking T::ALL and threading each variant into either the
        // middle-band or extremal collection recovers T::ALL element-
        // for-element in declaration order — every variant lands in
        // EXACTLY ONE of the two projections on non-empty slices.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let middle_band = <StubKind as ClosedSet>::middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    let via_union: Vec<StubKind> = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .filter(|v| middle_band.contains(v) || extremal.contains(v))
                        .collect();
                    assert_eq!(
                        via_union.as_slice(),
                        <StubKind as ClosedSet>::ALL,
                        "T::middle_band_variants({triple:?}) interleaved with T::extremal_variants({triple:?}) diverged from T::ALL — the (extreme / middle) partition covering identity was violated on a non-empty slice",
                    );
                }
            }
        }
    }

    #[test]
    fn middle_band_variants_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // the ordering-agnostic max/min-fold pair + a walk over T::ALL
        // in declaration order; reversing `items` preserves its
        // variant multiset, so the projection is a function of that
        // multiset alone.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::middle_band_variants(&triple);
                    let via_reversed = <StubKind as ClosedSet>::middle_band_variants(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::middle_band_variants({triple:?}) diverged from T::middle_band_variants({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

