    #[test]
    fn sorted_middle_band_variants_returns_the_middle_target_only_on_the_bimodal_triple_at_cardinality_gte_three(
    ) {
        // BIMODAL-TRIPLE CONTRACT AT CARDINALITY `>= 3`: on
        // `[T::ALL[0], T::ALL[0], T::ALL[1]]` the histogram is
        // (T::ALL[0] -> 2 == max, T::ALL[1] -> 1 == MIDDLE, T::ALL[2]
        // -> 0 == min); T::ALL[1] is the SOLE inhabitant sitting
        // strictly between max `2` and min `0`, so the lex-order
        // complement projection MUST return the singleton
        // `vec![T::ALL[1]]` regardless of walk order (the ordering
        // axis DEGENERATES on the single-inhabitant middle band).
        // LOAD-BEARING SOLE canonical fixture where this projection
        // populates a proper subset of T::sorted_variants.
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        let bimodal_triple = [
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[1],
        ];
        let sorted_middle_band =
            <StubKind as ClosedSet>::sorted_middle_band_variants(&bimodal_triple);
        let expected = vec![<StubKind as ClosedSet>::ALL[1]];
        assert_eq!(
            sorted_middle_band, expected,
            "T::sorted_middle_band_variants({bimodal_triple:?}) diverged from vec![T::ALL[1]] on the bimodal-triple fixpoint — the middle-band target T::ALL[1] MUST be included as the SOLE inhabitant and every other variant MUST be excluded regardless of walk order",
        );
    }

    #[test]
    fn sorted_middle_band_variants_len_agrees_with_count_middle_band_variants_across_every_triple()
    {
        // LENGTH-COMPOSITION IDENTITY: for every slice `items`,
        // `T::sorted_middle_band_variants(items).len() == T::count_middle_band_variants(items)`
        // — the plural's LEN equals the just-lifted cardinality-count
        // aggregate because both projections filter under the same
        // direction-composition predicate; ordering does NOT affect
        // cardinality.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_middle_band_variants(empty).len(),
            <StubKind as ClosedSet>::count_middle_band_variants(empty),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_plural =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple).len();
                    let via_scalar = <StubKind as ClosedSet>::count_middle_band_variants(&triple);
                    assert_eq!(
                        via_plural, via_scalar,
                        "T::sorted_middle_band_variants({triple:?}).len() diverged from T::count_middle_band_variants({triple:?}) — the length-composition identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_middle_band_variants_agrees_with_filter_of_is_middle_band_variant_of_across_every_triple(
    ) {
        // FILTER-COUNT IDENTITY: for every slice `items`,
        // `T::sorted_middle_band_variants(items) == T::sorted_variants().into_iter().filter(|&v| T::is_middle_band_variant_of(v, items)).collect()`
        // — the sharpened max/min-fold body agrees with the naive
        // per-target filter over T::sorted_variants on the
        // composition-shape axis.
        let empty: &[StubKind] = &[];
        let via_sharpened = <StubKind as ClosedSet>::sorted_middle_band_variants(empty);
        let via_naive: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
            .into_iter()
            .filter(|&v| <StubKind as ClosedSet>::is_middle_band_variant_of(v, empty))
            .collect();
        assert_eq!(via_sharpened, via_naive);
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_sharpened =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple);
                    let via_naive: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
                        .into_iter()
                        .filter(|&v| <StubKind as ClosedSet>::is_middle_band_variant_of(v, &triple))
                        .collect();
                    assert_eq!(
                        via_sharpened, via_naive,
                        "T::sorted_middle_band_variants({triple:?}) diverged from T::sorted_variants().into_iter().filter(|v| T::is_middle_band_variant_of(v, {triple:?})).collect() — the filter-count identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_middle_band_variants_agrees_with_lex_set_difference_of_sorted_variants_and_extremal_variants_across_every_triple(
    ) {
        // COMPLEMENT-COMPOSITION IDENTITY: for every NON-EMPTY slice
        // `items`, `T::sorted_middle_band_variants(items)` equals the
        // LEX-ORDER set-difference of T::sorted_variants() and
        // T::extremal_variants(items). On the empty slice the middle-
        // band projection collapses to Vec::new() via its non-emptiness
        // guard while the naive lex-set-difference walks
        // T::sorted_variants() and finds nothing in the empty
        // extremal_variants — the identity holds ONLY on non-empty
        // slices.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_middle_band =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    let via_diff: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
                        .into_iter()
                        .filter(|v| !extremal.contains(v))
                        .collect();
                    assert_eq!(
                        via_middle_band, via_diff,
                        "T::sorted_middle_band_variants({triple:?}) diverged from the lex-order set-difference of T::sorted_variants() and T::extremal_variants({triple:?}) — the complement-composition identity was violated on a non-empty slice",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_middle_band_variants_and_extremal_variants_are_disjoint_across_every_triple() {
        // DISJOINTNESS IDENTITY: for every slice `items`,
        // `T::sorted_middle_band_variants(items)` and
        // `T::extremal_variants(items)` share NO common variant — the
        // (extreme / middle) partition of the closed set on non-empty
        // slices is DISJOINT by construction (a variant's count either
        // sits at max/min or strictly between, never both). On the
        // empty slice both collapse to Vec::new() and disjointness
        // holds trivially.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let sorted_middle_band =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    for v in sorted_middle_band.iter() {
                        assert!(
                            !extremal.contains(v),
                            "T::sorted_middle_band_variants({triple:?}) shares variant {v:?} with T::extremal_variants({triple:?}) — the (extreme / middle) partition disjointness identity was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn sorted_middle_band_variants_is_a_lex_permutation_of_middle_band_variants_across_every_triple(
    ) {
        // MULTISET-AGREEMENT IDENTITY: for every slice `items`,
        // `T::sorted_middle_band_variants(items)` is a LEX-ORDER
        // PERMUTATION of `T::middle_band_variants(items)` — both
        // projections filter under the same strict-interior conjunction
        // `c != max && c != min` and agree as multisets, differing
        // ONLY in walk order (declaration vs lex). Sweeping every
        // length-3 triple pins the multiset-equality identity by
        // asserting the sorted-index projections agree element-for-
        // element.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let mut decl_indices: Vec<usize> =
                        <StubKind as ClosedSet>::middle_band_variants(&triple)
                            .into_iter()
                            .map(<StubKind as ClosedSet>::index_of)
                            .collect();
                    let mut lex_indices: Vec<usize> =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple)
                            .into_iter()
                            .map(<StubKind as ClosedSet>::index_of)
                            .collect();
                    decl_indices.sort_unstable();
                    lex_indices.sort_unstable();
                    assert_eq!(
                        decl_indices, lex_indices,
                        "T::sorted_middle_band_variants({triple:?}) and T::middle_band_variants({triple:?}) diverged as multisets — both projections MUST filter under the same strict-interior predicate and thus agree as multisets, differing ONLY in walk order",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_middle_band_variants_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // the ordering-agnostic max/min-fold pair + a walk over
        // T::sorted_variants (which does NOT depend on `items`
        // ordering); reversing `items` preserves its variant multiset,
        // so the projection is a function of that multiset alone.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::sorted_middle_band_variants(&triple);
                    let via_reversed =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::sorted_middle_band_variants({triple:?}) diverged from T::sorted_middle_band_variants({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_empty_drift_in_sorted_middle_band_variants() {
        // Drift catch — clause (152)'s bimodal-triple arm at
        // cardinality `>= 3` fires when an override folds the set-
        // level sorted middle-band witness-collection onto `Vec::new()`
        // unconditionally, because the bimodal-triple fixture is the
        // SOLE canonical NON-EMPTY witness of this projection at the
        // lex arm.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedSortedMiddleBandVariantsEmptyKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedSortedMiddleBandVariantsEmptyKind(pub String);

        impl core::fmt::Display for UnknownDriftedSortedMiddleBandVariantsEmptyKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted sorted middle band variants empty kind: {}",
                    self.0
                )
            }
        }

        impl DriftedSortedMiddleBandVariantsEmptyKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedSortedMiddleBandVariantsEmptyKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted sorted middle band variants empty kind";
            type Unknown = UnknownDriftedSortedMiddleBandVariantsEmptyKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedSortedMiddleBandVariantsEmptyKind(s.to_owned())
            }
            fn sorted_middle_band_variants(_items: &[Self]) -> Vec<Self> {
                // Drift: return Vec::new() regardless. Fires on the
                // bimodal-triple arm at
                // `Vec::new() != vec![T::ALL[1]]`.
                Vec::new()
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedSortedMiddleBandVariantsEmptyKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedSortedMiddleBandVariantsEmptyKind whose sorted_middle_band_variants override folds onto Vec::new() unconditionally — clause (152)'s bimodal-triple arm MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_all_drift_in_sorted_middle_band_variants() {
        // Drift catch — clause (152)'s empty-slice + full-set +
        // doubled-full-set + matching-singleton + bimodal-triple
        // fixpoint arms fire when an override folds the set-level
        // sorted middle-band witness-collection onto
        // `T::sorted_variants()` unconditionally.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedSortedMiddleBandVariantsAllKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedSortedMiddleBandVariantsAllKind(pub String);

        impl core::fmt::Display for UnknownDriftedSortedMiddleBandVariantsAllKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted sorted middle band variants all kind: {}",
                    self.0
                )
            }
        }

        impl DriftedSortedMiddleBandVariantsAllKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedSortedMiddleBandVariantsAllKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted sorted middle band variants all kind";
            type Unknown = UnknownDriftedSortedMiddleBandVariantsAllKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedSortedMiddleBandVariantsAllKind(s.to_owned())
            }
            fn sorted_middle_band_variants(_items: &[Self]) -> Vec<Self> {
                // Drift: return T::sorted_variants() regardless. Fires
                // on the empty-slice arm at
                // `T::sorted_variants() != Vec::new()` AND on every
                // flat-histogram arm (full-set, doubled-full-set,
                // matching-singleton) AND on the bimodal-triple arm
                // (T::sorted_variants() != vec![T::ALL[1]]).
                <Self as ClosedSet>::sorted_variants()
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedSortedMiddleBandVariantsAllKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedSortedMiddleBandVariantsAllKind whose sorted_middle_band_variants override folds onto T::sorted_variants() unconditionally — clause (152)'s empty-slice + full-set + doubled-full-set + matching-singleton + bimodal-triple fixpoint arms MUST reject the drift",
        );
    }

    #[test]
    fn sorted_extremal_variants_returns_the_empty_vec_on_the_empty_slice_across_every_kind() {
        // EMPTY-SLICE CONTRACT (set-level × Vec<Self> × statistical-
        // aggregate × direction-composition × union × lex-order): the
        // empty slice hits zero positions, T::is_extremal_variant_of
        // carries a non-emptiness precondition at every target so the
        // lex-order union collection collapses to Vec::new(). The
        // empty guard is LOAD-BEARING for STRUCTURAL correctness — the
        // empty answer is a TYPED CONSEQUENCE of the non-emptiness
        // precondition, not an accidental collision with the union
        // filter arm on the (max == min == 0) degenerate histogram
        // (which would collapse the union predicate `c == max || c ==
        // min` onto `true` at EVERY variant and return
        // `T::sorted_variants()` — the WRONG structural answer).
        // Sibling posture to
        // `extremal_variants_returns_the_empty_vec_on_the_empty_slice_across_every_kind`
        // one ORDERING axis over: both projections hit their empty-Vec
        // fixpoint at the same endpoint.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_extremal_variants(empty),
            Vec::<StubKind>::new(),
            "T::sorted_extremal_variants(&[]) diverged from the empty-slice fixpoint Vec::new()",
        );
    }

    #[test]
    fn sorted_extremal_variants_returns_all_on_every_matching_singleton_across_every_variant() {
        // MATCHING-SINGLETON CONTRACT AT CARDINALITY `>= 2`: the sole
        // position hits `v` at count `1 == max` under
        // T::is_modal_variant_of, every non-target variant sits at
        // count `0 == min` under T::is_antimodal_variant_of, so every
        // variant of T::sorted_variants is extremal via one of the two
        // arms walked in lex order. LOAD-BEARING FULL-COVERAGE arm
        // DISCRIMINATING this LEX-ORDER UNION projection from
        // T::sorted_middle_band_variants (which returns Vec::new() on
        // the same fixture).
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        let sorted_all = <StubKind as ClosedSet>::sorted_variants();
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert_eq!(
                <StubKind as ClosedSet>::sorted_extremal_variants(&singleton),
                sorted_all,
                "T::sorted_extremal_variants({singleton:?}) diverged from T::sorted_variants() at the matching-singleton fixpoint at variant {v:?}",
            );
        }
    }

