    #[test]
    fn sorted_extremal_variants_returns_all_but_middle_band_on_the_bimodal_triple_at_cardinality_gte_three(
    ) {
        // BIMODAL-TRIPLE CONTRACT AT CARDINALITY `>= 3`: on
        // `[T::ALL[0], T::ALL[0], T::ALL[1]]` the histogram is
        // (T::ALL[0] -> 2 == max, T::ALL[1] -> 1 == MIDDLE, T::ALL[2]
        // -> 0 == min); T::ALL[1] is EXCLUDED from the union arm, and
        // T::ALL[0] + T::ALL[2] are INCLUDED via one of the two
        // extreme arms. LOAD-BEARING SOLE canonical fixture where this
        // projection populates a proper subset of T::sorted_variants
        // at cardinality `T::CARDINALITY - 1` (strictly between the
        // empty-vec and full-list fixpoints).
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        let bimodal_triple = [
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[1],
        ];
        let sorted_extremal = <StubKind as ClosedSet>::sorted_extremal_variants(&bimodal_triple);
        let expected: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
            .into_iter()
            .filter(|&v| {
                <StubKind as ClosedSet>::index_of(v)
                    != <StubKind as ClosedSet>::index_of(<StubKind as ClosedSet>::ALL[1])
            })
            .collect();
        assert_eq!(
            sorted_extremal.len(),
            <StubKind as ClosedSet>::CARDINALITY - 1,
            "T::sorted_extremal_variants(&bimodal_triple).len() diverged from T::CARDINALITY - 1 on the bimodal-triple fixpoint",
        );
        assert_eq!(
            sorted_extremal, expected,
            "T::sorted_extremal_variants({bimodal_triple:?}) diverged from T::sorted_variants() minus T::ALL[1] on the bimodal-triple fixpoint",
        );
    }

    #[test]
