    #[test]
    fn bimodal_variants_returns_all_iff_slice_is_non_empty_and_uniform_across_every_triple() {
        // UNIFORMITY-COLLAPSE DICHOTOMY: for every slice `items`,
        // `T::bimodal_variants(items) == T::ALL.to_vec()` iff `items`
        // is NON-EMPTY AND T::is_uniform(items) holds, else
        // `Vec::new()`. Pins the two-value dichotomy on every canonical
        // triple.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::bimodal_variants(empty),
            Vec::<StubKind>::new(),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let bimodal = <StubKind as ClosedSet>::bimodal_variants(&triple);
                    let is_uniform = <StubKind as ClosedSet>::is_uniform(&triple);
                    let expected: Vec<StubKind> = if is_uniform {
                        <StubKind as ClosedSet>::ALL.to_vec()
                    } else {
                        Vec::new()
                    };
                    assert_eq!(
                        bimodal, expected,
                        "T::bimodal_variants({triple:?}) diverged from the uniformity-collapse dichotomy (is_uniform = {is_uniform}) — the two-value dichotomy identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn bimodal_variants_is_subset_of_extremal_variants_across_every_triple() {
        // INCLUSION IDENTITY: for every slice `items`,
        // `T::bimodal_variants(items) ⊆ T::extremal_variants(items)`
        // as multisets — every variant sitting at BOTH extremes
        // trivially sits at AT LEAST ONE extreme, so the intersection
        // subset injects into the union superset.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let bimodal = <StubKind as ClosedSet>::bimodal_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    for v in bimodal.iter() {
                        assert!(
                            extremal.contains(v),
                            "T::bimodal_variants({triple:?}) contains {v:?} but T::extremal_variants({triple:?}) does not — the intersection ⊆ union inclusion identity was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn bimodal_variants_and_middle_band_variants_are_disjoint_across_every_triple() {
        // DISJOINTNESS IDENTITY: for every slice `items`,
        // `T::bimodal_variants(items)` and
        // `T::middle_band_variants(items)` share NO common variant —
        // every bimodal target sits AT the max/min collapsed extremes
        // and every middle-band target sits STRICTLY between them, so
        // the two arms are mutually exclusive by construction.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let bimodal = <StubKind as ClosedSet>::bimodal_variants(&triple);
                    let middle_band = <StubKind as ClosedSet>::middle_band_variants(&triple);
                    for v in bimodal.iter() {
                        assert!(
                            !middle_band.contains(v),
                            "T::bimodal_variants({triple:?}) shares variant {v:?} with T::middle_band_variants({triple:?}) — the (bimodal / middle-band) disjointness identity was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn bimodal_variants_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // the ordering-agnostic T::is_uniform predicate + a walk over
        // T::ALL in declaration order; reversing `items` preserves its
        // variant multiset, so the projection is a function of that
        // multiset alone.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::bimodal_variants(&triple);
                    let via_reversed = <StubKind as ClosedSet>::bimodal_variants(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::bimodal_variants({triple:?}) diverged from T::bimodal_variants({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_empty_drift_in_bimodal_variants() {
        // Drift catch — clause (154)'s full-set + doubled-full-set
        // arms fire when an override folds the set-level bimodal
        // witness-collection onto `Vec::new()` unconditionally, because
        // the flat-histogram fixpoints pin the projection to
        // T::ALL.to_vec().
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedBimodalVariantsEmptyKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedBimodalVariantsEmptyKind(pub String);

        impl core::fmt::Display for UnknownDriftedBimodalVariantsEmptyKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(f, "unknown drifted bimodal variants empty kind: {}", self.0)
            }
        }

        impl DriftedBimodalVariantsEmptyKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedBimodalVariantsEmptyKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted bimodal variants empty kind";
            type Unknown = UnknownDriftedBimodalVariantsEmptyKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedBimodalVariantsEmptyKind(s.to_owned())
            }
            fn bimodal_variants(_items: &[Self]) -> Vec<Self> {
                // Drift: return Vec::new() regardless. Fires on both
                // flat-histogram fixpoint arms at `Vec::new() !=
                // T::ALL.to_vec()`.
                Vec::new()
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedBimodalVariantsEmptyKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedBimodalVariantsEmptyKind whose bimodal_variants override folds onto Vec::new() unconditionally — clause (154)'s full-set + doubled-full-set fixpoint arms MUST reject the drift",
        );
    }

