    #[test]
    fn sorted_middle_band_variant_returns_sorted_all_1_on_the_bimodal_triple_at_cardinality_gte_three(
    ) {
        // BIMODAL-TRIPLE CONTRACT AT CARDINALITY `>= 3`: on
        // `[T::ALL[0], T::ALL[0], T::ALL[1]]` the histogram is
        // (T::ALL[0] -> 2 == max, T::ALL[1] -> 1 == MIDDLE, T::ALL[2]
        // -> 0 == min); the LEX-order sweep visits variants in the
        // ASCII order of their labels and commits at the FIRST
        // variant satisfying `c != max && c != min`. On StubKind where
        // declaration and lex orders agree ("alpha", "beta", "gamma"),
        // T::sorted_variants()[0] == T::ALL[0] fails at `c == max`,
        // and T::sorted_variants()[1] == T::ALL[1] is the FIRST
        // lex-order variant satisfying the strict interior — the
        // projection lands on Some(T::sorted_variants()[1]) — the
        // SOLE canonical fixture on the modal-aggregation matrix's
        // fixture window where this projection returns a Some value.
        // Sibling posture to
        // `middle_band_variant_returns_all_1_on_the_bimodal_triple_at_cardinality_gte_three`
        // one ORDERING axis over: on the StubKind carrier where
        // declaration and lex orders coincide, the two projections
        // agree byte-for-byte on this fixture.
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        let bimodal_triple = [
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[1],
        ];
        let sorted_variants = <StubKind as ClosedSet>::sorted_variants();
        assert_eq!(
            <StubKind as ClosedSet>::sorted_middle_band_variant(&bimodal_triple),
            Some(sorted_variants[1]),
            "T::sorted_middle_band_variant({bimodal_triple:?}) diverged from Some(T::sorted_variants()[1]) at the bimodal-triple fixpoint",
        );
    }

