    #[test]
    fn assert_closed_set_well_formed_catches_always_none_drift_in_sorted_bimodal_variant() {
        // Drift catch — clause (161)'s full-set + doubled-full-set
        // fixpoint arms fire when an override folds the set-level
        // LEX-order direction-composition intersection first-witness
        // onto None unconditionally. Fires on the flat-histogram Some
        // arms at `None != Some(T::sorted_first())`.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedSortedBimodalVariantNoneKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedSortedBimodalVariantNoneKind(pub String);

        impl core::fmt::Display for UnknownDriftedSortedBimodalVariantNoneKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted sorted bimodal variant none kind: {}",
                    self.0
                )
            }
        }

        impl DriftedSortedBimodalVariantNoneKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedSortedBimodalVariantNoneKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted sorted bimodal variant none kind";
            type Unknown = UnknownDriftedSortedBimodalVariantNoneKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedSortedBimodalVariantNoneKind(s.to_owned())
            }
            fn sorted_bimodal_variant(_items: &[Self]) -> Option<Self> {
                // Drift: return None regardless. Fires on the full-set
                // + doubled-full-set arms at
                // `None != Some(T::sorted_first())`.
                None
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedSortedBimodalVariantNoneKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedSortedBimodalVariantNoneKind whose sorted_bimodal_variant override folds onto None unconditionally — clause (161)'s full-set + doubled-full-set fixpoint arms MUST reject the drift (the SOLE Some-arms on the canonical fixture window)",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_some_sorted_first_drift_in_sorted_bimodal_variant(
    ) {
        // Drift catch — clause (161)'s empty-slice + matching-singleton
        // + bimodal-triple fixpoint arms fire when an override folds
        // the set-level LEX-order direction-composition intersection
        // first-witness onto Some(T::sorted_first()) unconditionally.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedSortedBimodalVariantSomeKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedSortedBimodalVariantSomeKind(pub String);

        impl core::fmt::Display for UnknownDriftedSortedBimodalVariantSomeKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted sorted bimodal variant some kind: {}",
                    self.0
                )
            }
        }

        impl DriftedSortedBimodalVariantSomeKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedSortedBimodalVariantSomeKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted sorted bimodal variant some kind";
            type Unknown = UnknownDriftedSortedBimodalVariantSomeKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedSortedBimodalVariantSomeKind(s.to_owned())
            }
            fn sorted_bimodal_variant(_items: &[Self]) -> Option<Self> {
                // Drift: return Some(T::sorted_first()) regardless.
                // Fires on the empty-slice + matching-singleton +
                // bimodal-triple arms at
                // `Some(T::sorted_first()) != None`.
                Some(<Self as ClosedSet>::sorted_first())
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedSortedBimodalVariantSomeKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedSortedBimodalVariantSomeKind whose sorted_bimodal_variant override folds onto Some(T::sorted_first()) unconditionally — clause (161)'s empty-slice + matching-singleton + bimodal-triple fixpoint arms MUST reject the drift",
        );
    }

