    #[test]
    fn has_unique_middle_band_variant_equals_count_middle_band_variants_eq_one_across_every_triple()
    {
        // COUNT-COMPOSITION IDENTITY: for every slice `items`,
        // `T::has_unique_middle_band_variant(items) ==
        // (T::count_middle_band_variants(items) == 1)` — the canonical
        // form the body uses. Sweeping every length-3 triple pins the
        // identity across the full 27-corner domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate =
                        <StubKind as ClosedSet>::has_unique_middle_band_variant(&triple);
                    let via_count =
                        <StubKind as ClosedSet>::count_middle_band_variants(&triple) == 1;
                    assert_eq!(
                        via_predicate, via_count,
                        "T::has_unique_middle_band_variant({triple:?}) diverged from (T::count_middle_band_variants({triple:?}) == 1) — the count-composition identity was violated",
                    );
                }
            }
        }
        // Empty-slice endpoint: predicate is `false`, count is `0`,
        // `0 == 1` is `false`.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::has_unique_middle_band_variant(empty),
            <StubKind as ClosedSet>::count_middle_band_variants(empty) == 1,
        );
    }

