    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_has_unique_bimodal_variant() {
        // Drift catch — clause (164)'s empty-slice + flat-histogram +
        // matching-singleton + bimodal-triple fixpoint arms fire when
        // an override folds the set-level bimodal-intersection
        // uniqueness predicate onto `true` unconditionally. Empty-
        // slice arm produces `true != false` at the count-composition
        // identity (`0 != 1`); every flat-histogram + matching-
        // singleton + bimodal-triple arm at cardinality `>= 2`
        // produces `true != false` (`T::CARDINALITY >= 2 != 1` on
        // flat, `0 != 1` on non-flat).
        //
        // Note: no `always-false` drift-catch peer is possible on a
        // cardinality-3 stub — at `T::CARDINALITY >= 2` the correct
        // bimodal-uniqueness answer is `false` on EVERY canonical
        // fixture, so an always-false override matches truth
        // structurally (the degenerate-opener property clause (164)
        // documents). The structural catch for `false`-drifting
        // overrides sits at `T::CARDINALITY == 1` in clause (164)'s
        // count-composition arm on the full-set fixpoint, out of
        // reach of a multi-variant stub.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedHasUniqueBimodalVariantTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedHasUniqueBimodalVariantTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedHasUniqueBimodalVariantTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted has_unique_bimodal_variant true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedHasUniqueBimodalVariantTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedHasUniqueBimodalVariantTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted has_unique_bimodal_variant true kind";
            type Unknown = UnknownDriftedHasUniqueBimodalVariantTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedHasUniqueBimodalVariantTrueKind(s.to_owned())
            }
            fn has_unique_bimodal_variant(_items: &[Self]) -> bool {
                // Drift: return `true` regardless. Fires clause (164)'s
                // empty-slice arm AND every flat-histogram + matching-
                // singleton + bimodal-triple fixpoint arm at
                // cardinality >= 2.
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedHasUniqueBimodalVariantTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedHasUniqueBimodalVariantTrueKind whose has_unique_bimodal_variant override folds onto `true` unconditionally — clause (164)'s empty-slice + flat-histogram + matching-singleton + bimodal-triple fixpoint arms MUST reject the drift",
        );
    }

