    #[test]
    fn is_unique_extremal_variant_of_equals_extremal_membership_and_unique_extremal_variant_across_every_target_and_triple(
    ) {
        // UNION-CONJUNCTION IDENTITY: for every slice `items` and every
        // target `v`,
        // `T::is_unique_extremal_variant_of(v, items) == (T::is_extremal_variant_of(v, items) && T::has_unique_extremal_variant(items))`
        // — the per-target uniqueness predicate is EXACTLY the conjunction
        // of the per-target union membership predicate with the set-level
        // extremal-uniqueness scalar. The canonical form the body uses.
        for target in <StubKind as ClosedSet>::ALL.iter().copied() {
            for a in <StubKind as ClosedSet>::ALL.iter().copied() {
                for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                    for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let triple = [a, b, c];
                        let via_predicate =
                            <StubKind as ClosedSet>::is_unique_extremal_variant_of(target, &triple);
                        let via_conjunction =
                            <StubKind as ClosedSet>::is_extremal_variant_of(target, &triple)
                                && <StubKind as ClosedSet>::has_unique_extremal_variant(&triple);
                        assert_eq!(
                            via_predicate, via_conjunction,
                            "T::is_unique_extremal_variant_of({target:?}, {triple:?}) diverged from (T::is_extremal_variant_of && T::has_unique_extremal_variant) — the union-conjunction identity was violated",
                        );
                    }
                }
            }
        }
    }

