    #[test]
    fn is_unique_extremal_variant_of_agrees_with_direction_disjunction_gated_by_unique_extremal_variant_across_every_target_and_triple(
    ) {
        // DIRECTION-DISJUNCTION IDENTITY: for every slice `items` and
        // every target `v`,
        // T::is_unique_extremal_variant_of(v, items) ==
        //     ((T::is_modal_variant_of(v, items) || T::is_antimodal_variant_of(v, items))
        //      && T::has_unique_extremal_variant(items))
        // — the per-target union unique-tie predicate factors through the
        // per-target modal/antimodal membership pair under `||` when the
        // SET-LEVEL extremal-uniqueness bit holds. Note: this identity
        // uses the UNSHARPENED per-target modal/antimodal membership
        // predicates, NOT the direction-anchored per-target unique-tie
        // sharpenings — those pin per-target argmax/argmin uniqueness
        // ANCHORED to each band, distinct from the UNION unique-tie
        // predicate under sharpening here.
        for target in <StubKind as ClosedSet>::ALL.iter().copied() {
            for a in <StubKind as ClosedSet>::ALL.iter().copied() {
                for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                    for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let triple = [a, b, c];
                        let via_predicate =
                            <StubKind as ClosedSet>::is_unique_extremal_variant_of(target, &triple);
                        let via_disjunction =
                            (<StubKind as ClosedSet>::is_modal_variant_of(target, &triple)
                                || <StubKind as ClosedSet>::is_antimodal_variant_of(
                                    target, &triple,
                                ))
                                && <StubKind as ClosedSet>::has_unique_extremal_variant(&triple);
                        assert_eq!(
                            via_predicate, via_disjunction,
                            "T::is_unique_extremal_variant_of({target:?}, {triple:?}) diverged from ((is_modal || is_antimodal) && has_unique_extremal) — the direction-disjunction identity was violated",
                        );
                    }
                }
            }
        }
    }

