    #[test]
    fn is_unique_bimodal_variant_of_returns_false_on_the_empty_slice_across_every_target() {
        // EMPTY-SLICE CONTRACT: T::is_unique_bimodal_variant_of(v, &[])
        // is `false` for every target v — T::is_bimodal_variant_of
        // falsifies universally at the empty slice via its
        // is_modal_variant_of guard, and `false && _` short-circuits
        // to `false`.
        let empty: &[StubKind] = &[];
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            assert!(
                !<StubKind as ClosedSet>::is_unique_bimodal_variant_of(v, empty),
                "T::is_unique_bimodal_variant_of({v:?}, &[]) diverged from the empty-slice fixpoint `false`",
            );
        }
    }

    #[test]
    fn is_unique_bimodal_variant_of_returns_false_on_the_matching_singleton_across_every_target() {
        // MATCHING-SINGLETON CONTRACT AT CARDINALITY >= 2:
        // T::is_unique_bimodal_variant_of(v, &[v]) is `false` for
        // every target v — a singleton has max == 1 at v and min == 0
        // at every non-target; v sits on the argmax band but NOT on
        // the argmin band (count 1 != 0 == min), so
        // T::is_bimodal_variant_of falsifies at v via its argmin arm
        // and the conjunction lands on `false` through the membership
        // arm.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert!(
                !<StubKind as ClosedSet>::is_unique_bimodal_variant_of(v, &singleton),
                "T::is_unique_bimodal_variant_of({v:?}, [{v:?}]) diverged from the matching-singleton fixpoint `false` at cardinality 3",
            );
        }
    }

    #[test]
    fn is_unique_bimodal_variant_of_returns_false_on_the_non_matching_singleton_across_every_target_pair(
    ) {
        // NON-MATCHING-SINGLETON CONTRACT:
        // T::is_unique_bimodal_variant_of(v, &[w]) is `false` for
        // every target v and slice-element w with T::index_of(v) !=
        // T::index_of(w) — the singleton pins w at count 1 == max
        // and every non-w (including v) at count 0 == min; max != min
        // collapses the intersection band to empty, so
        // T::is_bimodal_variant_of falsifies at every target.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            for w in <StubKind as ClosedSet>::ALL.iter().copied() {
                if <StubKind as ClosedSet>::index_of(v) != <StubKind as ClosedSet>::index_of(w) {
                    let singleton = [w];
                    assert!(
                        !<StubKind as ClosedSet>::is_unique_bimodal_variant_of(v, &singleton),
                        "T::is_unique_bimodal_variant_of({v:?}, [{w:?}]) diverged from the non-matching-singleton fixpoint `false`",
                    );
                }
            }
        }
    }

