    #[test]
    fn is_unique_bimodal_variant_of_equals_bimodal_membership_and_unique_bimodal_variant_across_every_target_and_triple(
    ) {
        // INTERSECTION-CONJUNCTION IDENTITY: for every slice `items`
        // and every target v, T::is_unique_bimodal_variant_of(v,
        // items) == T::is_bimodal_variant_of(v, items) &&
        // T::has_unique_bimodal_variant(items). Sweeping every length-
        // 3 triple × every target pins the identity across the full
        // 3×27 = 81-corner (target × triple) matrix.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let via_trait =
                            <StubKind as ClosedSet>::is_unique_bimodal_variant_of(v, &triple);
                        let via_composition =
                            <StubKind as ClosedSet>::is_bimodal_variant_of(v, &triple)
                                && <StubKind as ClosedSet>::has_unique_bimodal_variant(&triple);
                        assert_eq!(
                            via_trait, via_composition,
                            "T::is_unique_bimodal_variant_of({v:?}, {triple:?}) diverged from is_bimodal_variant_of && has_unique_bimodal_variant — the composition identity was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn is_unique_bimodal_variant_of_count_equals_has_unique_bimodal_variant_as_usize_across_every_triple(
    ) {
        // AT-MOST-ONE-TARGET IDENTITY: for every slice `items`,
        // T::ALL.iter().filter(|&v| T::is_unique_bimodal_variant_of(v, items)).count()
        // == usize::from(T::has_unique_bimodal_variant(items)). At
        // cardinality >= 2 on multi-variant fixtures both sides
        // collapse to 0 (the intersection direction-composition axis
        // is DOUBLY DEGENERATE at cardinality >= 2), so the identity
        // holds trivially. Sibling posture to
        // is_unique_middle_band_variant_of_count_equals_has_unique_middle_band_variant_as_usize
        // AND is_unique_extremal_variant_of_count_equals_has_unique_extremal_variant_as_usize
        // one COMBINATOR axis over.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let filter_count = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .filter(|&v| {
                            <StubKind as ClosedSet>::is_unique_bimodal_variant_of(v, &triple)
                        })
                        .count();
                    let expected =
                        usize::from(<StubKind as ClosedSet>::has_unique_bimodal_variant(&triple));
                    assert_eq!(
                        filter_count, expected,
                        "T::ALL.iter().filter(|v| T::is_unique_bimodal_variant_of(*v, {triple:?})).count() == {filter_count} drifted from usize::from(T::has_unique_bimodal_variant({triple:?})) == {expected} — the at-most-one-target contract was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn is_unique_bimodal_variant_of_is_invariant_under_slice_reversal_across_every_target_and_triple(
    ) {
        // SLICE-REVERSAL INVARIANCE: T::is_unique_bimodal_variant_of(v,
        // items) == T::is_unique_bimodal_variant_of(v, reversed items)
        // on every slice and every target — reversing a slice
        // preserves its multiset of variant identities, and both
        // underlying primitives (T::is_bimodal_variant_of via
        // T::count_occurrences_of + T::max_variant_count +
        // T::min_variant_count, T::has_unique_bimodal_variant via
        // T::count_bimodal_variants) are fixpoints of slice reversal.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let forward = [a, b, c];
                    let reversed = [c, b, a];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        assert_eq!(
                            <StubKind as ClosedSet>::is_unique_bimodal_variant_of(v, &forward),
                            <StubKind as ClosedSet>::is_unique_bimodal_variant_of(v, &reversed),
                            "T::is_unique_bimodal_variant_of({v:?}, {forward:?}) diverged from T::is_unique_bimodal_variant_of({v:?}, {reversed:?}) — slice-reversal invariance was violated",
                        );
                    }
                }
            }
        }
    }

