    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_has_unique_repeating_variant() {
        // Drift catch — clause (171)'s empty-slice + full-set +
        // doubled-full-set fixpoint arms fire when an override folds
        // the set-level strict-repeat uniqueness predicate onto `true`
        // unconditionally. Empty-slice arm produces `true != false` at
        // the count-composition identity (`0 != 1`); full-set arm
        // produces `true != false` (`0 != 1`); doubled-full-set arm
        // produces `true != false` at cardinality >= 2 (`T::CARDINALITY
        // >= 2 != 1`).
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedHasUniqueRepeatingVariantTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedHasUniqueRepeatingVariantTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedHasUniqueRepeatingVariantTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted has_unique_repeating_variant true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedHasUniqueRepeatingVariantTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedHasUniqueRepeatingVariantTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted has_unique_repeating_variant true kind";
            type Unknown = UnknownDriftedHasUniqueRepeatingVariantTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedHasUniqueRepeatingVariantTrueKind(s.to_owned())
            }
            fn has_unique_repeating_variant(_items: &[Self]) -> bool {
                // Drift: return `true` regardless. Fires clause (171)'s
                // empty-slice + full-set + doubled-full-set fixpoint
                // arms all at `true != false`.
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedHasUniqueRepeatingVariantTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedHasUniqueRepeatingVariantTrueKind whose has_unique_repeating_variant override folds onto `true` unconditionally — clause (171)'s empty-slice + full-set + doubled-full-set fixpoint arms MUST reject the drift",
        );
    }

