    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_is_unique_repeating_variant_of() {
        // Drift catch — clause (173)'s empty-slice + matching-
        // singleton + non-matching-singleton + full-set + doubled-
        // full-set fixpoint arms fire when an override folds the
        // per-target unique-strict-repeat predicate onto `true`
        // regardless of target. Every negative canonical fixpoint
        // pins the projection at `false`, so an always-true override
        // bifurcates every negative arm at `true != false`.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedIsUniqueRepeatingVariantOfTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedIsUniqueRepeatingVariantOfTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedIsUniqueRepeatingVariantOfTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted is_unique_repeating_variant_of true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedIsUniqueRepeatingVariantOfTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedIsUniqueRepeatingVariantOfTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted is_unique_repeating_variant_of true kind";
            type Unknown = UnknownDriftedIsUniqueRepeatingVariantOfTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedIsUniqueRepeatingVariantOfTrueKind(s.to_owned())
            }
            fn is_unique_repeating_variant_of(_target: Self, _items: &[Self]) -> bool {
                // Drift: return `true` regardless. Fires clause
                // (173)'s empty-slice + matching-singleton + non-
                // matching-singleton + full-set + doubled-full-set
                // fixpoint arms all at `true != false`.
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedIsUniqueRepeatingVariantOfTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedIsUniqueRepeatingVariantOfTrueKind whose is_unique_repeating_variant_of override folds onto `true` unconditionally — clause (173)'s empty-slice + matching-singleton + non-matching-singleton + full-set + doubled-full-set fixpoint arms MUST reject the drift",
        );
    }

