    #[test]
    fn assert_closed_set_well_formed_catches_always_some_first_drift_in_unique_unique_variant() {
        // Drift catch — clause (176)'s empty-slice + doubled-full-set
        // fixpoint arms fire when an override folds the set-level
        // unique-band witness projection onto `Some(T::first())`
        // unconditionally. Empty-slice arm produces `Some(T::ALL[0])
        // != None`; doubled-full-set arm at cardinality >= 2 produces
        // `Some(T::ALL[0]) != None`.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedUniqueUniqueVariantSomeKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedUniqueUniqueVariantSomeKind(pub String);

        impl core::fmt::Display for UnknownDriftedUniqueUniqueVariantSomeKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted unique_unique_variant some kind: {}",
                    self.0
                )
            }
        }

        impl DriftedUniqueUniqueVariantSomeKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedUniqueUniqueVariantSomeKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted unique_unique_variant some kind";
            type Unknown = UnknownDriftedUniqueUniqueVariantSomeKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedUniqueUniqueVariantSomeKind(s.to_owned())
            }
            fn unique_unique_variant(_items: &[Self]) -> Option<Self> {
                // Drift: return `Some(T::first())` regardless. Fires
                // clause (176)'s empty-slice + doubled-full-set
                // fixpoint arms at `Some(_) != None`. The full-set arm
                // at cardinality >= 2 also folds to `None` under the
                // canonical body, so this drift bifurcates there too.
                Some(Self::Alpha)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedUniqueUniqueVariantSomeKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedUniqueUniqueVariantSomeKind whose unique_unique_variant override folds onto `Some(T::first())` unconditionally — clause (176)'s empty-slice + doubled-full-set fixpoint arms MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_none_drift_in_unique_unique_variant() {
        // Drift catch — clause (176)'s bimodal-triple fixpoint arm at
        // cardinality >= 3 fires when an override folds the set-level
        // unique-band witness projection onto `None` unconditionally.
        // On `[T::ALL[0], T::ALL[0], T::ALL[1]]`
        // T::has_unique_unique_variant returns `true` and the
        // guarded-first-witness body lands on `Some(T::ALL[1])`, so a
        // `None` override bifurcates `None != Some(T::ALL[1])` at
        // this fixpoint. Additionally, at cardinality `>= 2` the
        // matching-singleton fixture `[v]` demands `Some(v)`, so an
        // always-`None` override bifurcates every matching-singleton
        // arm too — but the DEFAULT trait body's matching-singleton
        // contract lives at the test-level (per-implementor test
        // above), not in `assert_closed_set_well_formed`; the
        // bimodal-triple arm is what catches this drift structurally.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedUniqueUniqueVariantNoneKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedUniqueUniqueVariantNoneKind(pub String);

        impl core::fmt::Display for UnknownDriftedUniqueUniqueVariantNoneKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted unique_unique_variant none kind: {}",
                    self.0
                )
            }
        }

        impl DriftedUniqueUniqueVariantNoneKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedUniqueUniqueVariantNoneKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted unique_unique_variant none kind";
            type Unknown = UnknownDriftedUniqueUniqueVariantNoneKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedUniqueUniqueVariantNoneKind(s.to_owned())
            }
            fn unique_unique_variant(_items: &[Self]) -> Option<Self> {
                // Drift: return `None` regardless. Fires clause
                // (176)'s bimodal-triple fixpoint arm at cardinality
                // >= 3 at `None != Some(T::ALL[1])`.
                None
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedUniqueUniqueVariantNoneKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedUniqueUniqueVariantNoneKind whose unique_unique_variant override folds onto `None` unconditionally — clause (176)'s bimodal-triple fixpoint arm at cardinality >= 3 MUST reject the drift",
        );
    }

